409943	盾牌精通£Å获得盾牌精通技能：\r\n\r\n|T134963:24|t\r\n每当你格挡时，恢复最大法力值的8%，并提高护甲值，数值相当于盾牌护甲值的30%，最多可叠加5次。你的格挡几率提高10%，格挡值提高15%。\r\n\r\n每当你使用一个震击技能，高于10的每一点防御技能还会使你的法术强度提高4点，É15Ã。\r\nÇ
