409946	漩涡武器£Å获得漩涡武器技能：\r\n\r\n|T237584:24|t\r\n使用近战攻击Ê伤害后，你的下一个闪电箭、闪电链、次级治疗波或熔岩爆裂有一定几率获得Á和法力值消耗降低20%的效果。你的主手武器拥有风怒武器附魔时，触发几率提高50%，装备双手武器时额外提高50%。最多可叠加5次。效果É30Ã。Ç
409947	大地之盾£Å获得大地之盾技能：\r\n\r\n|T136089:24|t\r\n使用一层大地之盾保护目标，使其因受到伤害而损失的施法或引导时间缩短30%，被大地之盾保护的目标在受到攻击时可以恢复Æ9ÇÅÍ。该效果每数Ã只能生效一次，共可生效9次。大地之盾É10分钟，同一时间内只能给一个目标施放大地之盾。\r\nÇ
